"""OpenAI form elicitation with validated MCP responses."""

from __future__ import annotations

from typing import Any, Literal, cast

from mcp.server.elicitation import (
    AcceptedElicitation,
    CancelledElicitation,
    DeclinedElicitation,
    ElicitationResult,
    ElicitSchemaModelT,
)
from mcp.server.mcpserver.context import Context
from mcp.shared.message import ServerMessageMetadata
from mcp_types import ElicitRequestFormParams, ElicitResult, Request, ServerRequest
from pydantic import ValidationError

from openai_mcp_extensions.form._schema import render_form_schema
from openai_mcp_form_protocol import FormField, FormSchema, validate_form_selections

OPENAI_ELICITATION_EXTENSION_ID = "openai/elicitation"
OPENAI_ELICITATION_METHOD = "openai/elicitation/create"


class _OpenAIFormRequest(Request[ElicitRequestFormParams, Literal["openai/elicitation/create"]]):
    method: Literal["openai/elicitation/create"] = OPENAI_ELICITATION_METHOD


async def elicit_form(
    context: Context[Any, Any],
    *,
    message: str,
    schema: type[ElicitSchemaModelT],
) -> ElicitationResult[ElicitSchemaModelT]:
    """Request a form and return the validated Pydantic model."""

    capabilities = context.client_capabilities
    settings = (
        (capabilities.extensions or {}).get(OPENAI_ELICITATION_EXTENSION_ID)
        if capabilities
        else None
    )
    if not isinstance(settings, dict) or not isinstance(settings.get("form"), dict):
        raise ValueError(
            f"The MCP client does not support {OPENAI_ELICITATION_EXTENSION_ID} form requests"
        )

    requested_schema = render_form_schema(schema)
    request = _OpenAIFormRequest(
        params=ElicitRequestFormParams(
            message=message,
            requested_schema=requested_schema,
        ),
    )
    result = await context.session.send_request(
        cast(ServerRequest, request),
        ElicitResult,
        metadata=ServerMessageMetadata(
            related_request_id=context.request_context.request_id,
        ),
    )

    return validate_form_result(result, schema, requested_schema)


def validate_form_result(
    result: ElicitResult,
    schema: type[ElicitSchemaModelT],
    requested_schema: dict[str, Any],
) -> ElicitationResult[ElicitSchemaModelT]:
    if result.action == "accept":
        if result.content is None:
            raise ValueError("Received an accepted elicitation with no content")
        validate_form_selections(
            FormSchema[FormField].model_validate(requested_schema), result.content
        )
        try:
            validated_data = schema.model_validate(result.content)
        except ValidationError as error:
            raise ValueError(
                "Received an accepted elicitation whose content does not match the requested schema"
            ) from error
        return AcceptedElicitation(data=validated_data)
    if result.action == "decline":
        return DeclinedElicitation()
    return CancelledElicitation()

import assert from "node:assert/strict";
import test from "node:test";
import {
  OpenAIFormSchema,
  createOpenAIFormContentSchema,
  getResourcePath,
} from "../src/index.js";

test("resource context tolerates unrelated metadata and rejects malformed paths", () => {
  assert.equal(getResourcePath(undefined), undefined);
  assert.equal(
    getResourcePath({
      future: true,
      "openai/resource": { path: "/workspace/drawing.stl", future: true },
    }),
    "/workspace/drawing.stl",
  );
  assert.throws(() => getResourcePath({ "openai/resource": { path: 1 } }));
});

test("form answers enforce required fields, constraints, and supplied resource choices", () => {
  const form = OpenAIFormSchema.parse({
    type: "object",
    required: ["name", "quantity", "source"],
    properties: {
      name: { type: "string", minLength: 1 },
      quantity: { type: "integer", minimum: 1 },
      grid: { type: "boolean", default: true },
      source: {
        type: "string",
        format: "uri",
        "x-openai-input": {
          type: "resource",
          options: [{ uri: "file:///drawing.stl", name: "Drawing" }],
        },
      },
    },
  });
  const schema = createOpenAIFormContentSchema(form);
  const answer = { name: "bolt", quantity: 2, source: "file:///drawing.stl" };
  assert.deepEqual(schema.parse(answer), answer);
  for (const invalid of [
    { ...answer, quantity: 0 },
    { ...answer, quantity: "2" },
    { ...answer, name: "" },
    { ...answer, source: "file:///other.stl" },
    { name: "bolt" },
  ]) {
    assert.equal(schema.safeParse(invalid).success, false);
  }
  const missing = schema.safeParse({});
  assert.equal(missing.success, false);
  if (!missing.success)
    assert.ok(missing.error.issues.some((issue) => issue.path[0] === "name"));
});

test("form suggestions allow free input and resource selection modes remain distinct", () => {
  const suggested = OpenAIFormSchema.parse({
    type: "object",
    properties: {
      name: {
        type: "string",
        "x-openai-suggestions": [{ const: "bolt", title: "Bolt" }],
      },
      tags: { type: "array", items: { type: "string" } },
    },
  });
  assert.deepEqual(
    createOpenAIFormContentSchema(suggested).parse({
      name: "nut",
      tags: ["hardware", "metal"],
    }),
    { name: "nut", tags: ["hardware", "metal"] },
  );
  for (const extra of [{ userOptions: {} }, { selection: "implicit" }]) {
    const form = OpenAIFormSchema.parse({
      type: "object",
      properties: {
        source: {
          type: "array",
          items: { type: "string", format: "uri" },
          "x-openai-input": { type: "resource", options: [], ...extra },
        },
      },
    });
    assert.deepEqual(
      createOpenAIFormContentSchema(form).parse({
        source: ["file:///uploaded.stl"],
      }),
      { source: ["file:///uploaded.stl"] },
    );
  }
  assert.equal(
    OpenAIFormSchema.safeParse({
      type: "object",
      properties: {
        source: {
          type: "array",
          items: { type: "string", format: "uri" },
          default: ["file:///drawing.stl"],
          "x-openai-input": {
            type: "resource",
            options: [],
            selection: "implicit",
          },
        },
      },
    }).success,
    false,
  );
});

import assert from "node:assert/strict";
import test, { type TestContext } from "node:test";
import { App, type McpUiHostContext } from "@modelcontextprotocol/ext-apps";
import { AppBridge } from "@modelcontextprotocol/ext-apps/app-bridge";
import { InMemoryTransport } from "@modelcontextprotocol/sdk/inMemory.js";
import type { JSONRPCRequest } from "@modelcontextprotocol/sdk/types.js";
import { z } from "zod";
import { OpenAIExtensions } from "../src/app/index.js";

const features = Object.fromEntries(
  [
    "openai/files",
    "openai/message",
    "openai/modelContext",
    "openai/resource",
  ].map((key) => [key, {}]),
);

async function host(
  t: TestContext,
  experimental = features,
  hostContext: McpUiHostContext = {},
) {
  const app = new App(
    { name: "sdk-consumer", version: "1" },
    {},
    { autoResize: false },
  );
  const extensions = new OpenAIExtensions(app);
  const bridge = new AppBridge(
    null,
    { name: "sdk-host", version: "1" },
    {
      experimental,
      serverResources: {},
      message: { text: {} },
      updateModelContext: { structuredContent: {} },
    },
    { hostContext },
  );
  const [appTransport, hostTransport] = InMemoryTransport.createLinkedPair();
  t.after(async () => {
    await app.close();
    await bridge.close();
  });
  const requests: JSONRPCRequest[] = [];
  for (const transport of [appTransport, hostTransport]) {
    const send = transport.send.bind(transport);
    transport.send = async (message, options) => {
      const wire = JSON.parse(JSON.stringify(message));
      if (transport === appTransport && "method" in wire && "id" in wire)
        requests.push(wire);
      await send(wire, options);
    };
  }
  let reply: Record<string, unknown> = {};
  let failure: Error | undefined;
  for (const method of [
    "resources/read",
    "resources/subscribe",
    "resources/unsubscribe",
    "openai/resources/write",
    "openai/files/open",
    "ui/message",
    "ui/update-model-context",
  ]) {
    bridge.setRequestHandler(
      z.object({
        method: z.literal(method),
        params: z.record(z.string(), z.unknown()).optional(),
      }),
      async () => {
        if (failure) throw failure;
        return reply;
      },
    );
  }
  // Follow the documented setup: register the initial result before connecting.
  let received!: (value: unknown) => void;
  const initialResult = new Promise<unknown>((resolve) => {
    received = resolve;
  });
  app.ontoolresult = received;
  const initial = { content: [], structuredContent: { part: "bolt" } };
  bridge.oninitialized = () => {
    void bridge
      .sendToolInput({ arguments: {} })
      .then(() => bridge.sendToolResult(initial));
  };
  for (const feature of [
    "files",
    "message",
    "modelContext",
    "resources",
  ] as const)
    assert.equal(extensions[feature], undefined);
  await bridge.connect(hostTransport);
  await app.connect(appTransport);
  assert.deepEqual(await initialResult, initial);
  return {
    app,
    extensions,
    requests,
    reply(value: Record<string, unknown>) {
      reply = value;
    },
    fail(error: Error) {
      failure = error;
    },
    async context(value: McpUiHostContext) {
      const changed = new Promise<void>((resolve) => {
        const listener = () => {
          app.removeEventListener("hostcontextchanged", listener);
          resolve();
        };
        app.addEventListener("hostcontextchanged", listener);
      });
      await bridge.sendHostContextChange(value);
      await changed;
    },
    notify: (method: string, params: Record<string, unknown>) =>
      hostTransport.send({ jsonrpc: "2.0", method, params }),
  };
}

test("documented app setup receives its initial result and negotiated capabilities", async (t) => {
  const h = await host(t);
  assert.equal(h.requests[0]?.method, "ui/initialize");
  assert.deepEqual(h.requests[0]?.params?.appInfo, {
    name: "sdk-consumer",
    version: "1",
  });
  for (const feature of [
    "files",
    "message",
    "modelContext",
    "resources",
  ] as const)
    assert.ok(h.extensions[feature]);
  const unsupported = await host(t, {});
  for (const feature of [
    "files",
    "message",
    "modelContext",
    "resources",
  ] as const)
    assert.equal(unsupported.extensions[feature], undefined);
});

test("resource reads serialize representation metadata and return contents with ETags", async (t) => {
  const h = await host(t);
  const content = {
    uri: "file:///drawing.stl",
    blob: "Y2Fk",
    _meta: { "openai/resource": { etag: "v1", writable: true } },
  };
  h.reply({ contents: [content] });
  const result = await h.extensions.resources!.read({
    uri: content.uri,
    representation: "blob",
    _meta: { trace: "read-1", "openai/resource": { representation: "text" } },
  });
  assert.deepEqual(h.requests.at(-1)?.params, {
    uri: content.uri,
    _meta: { trace: "read-1", "openai/resource": { representation: "blob" } },
  });
  assert.equal(h.requests.at(-1)?.method, "resources/read");
  assert.deepEqual(result.contents, [
    { ...content, openaiMetadata: { etag: "v1", writable: true } },
  ]);
  h.reply({
    contents: [
      {
        uri: content.uri,
        text: "cad",
        _meta: { "openai/resource": { etag: 1 } },
      },
    ],
  });
  const text = await h.extensions.resources!.read({ uri: content.uri });
  const item = text.contents[0];
  assert.ok(item && "text" in item);
  assert.equal(item.text, "cad");
  assert.equal(item.openaiMetadata, undefined);
  h.reply({ contents: "malformed" });
  await assert.rejects(h.extensions.resources!.read({ uri: content.uri }));
});

test("resource writes preserve outcomes and reject malformed replies and host errors", async (t) => {
  const h = await host(t);
  const resources = h.extensions.resources!;
  for (const outcome of [
    { outcome: "saved", etag: "v2" },
    { outcome: "conflict", etag: "v3" },
    { outcome: "too-large", maxBytes: 1024 },
  ]) {
    h.reply(outcome);
    assert.deepEqual(
      await resources.write("file:///drawing.stl", {
        text: "cad",
        ifMatch: "v1",
      }),
      outcome,
    );
    assert.equal(h.requests.at(-1)?.method, "openai/resources/write");
    assert.deepEqual(h.requests.at(-1)?.params, {
      uri: "file:///drawing.stl",
      text: "cad",
      ifMatch: "v1",
    });
  }
  h.reply({ outcome: "saved", etag: "v4" });
  assert.deepEqual(
    await resources.write("file:///drawing.stl", { blob: "Y2Fk" }),
    { outcome: "saved", etag: "v4" },
  );
  assert.deepEqual(h.requests.at(-1)?.params, {
    uri: "file:///drawing.stl",
    blob: "Y2Fk",
  });
  const count = h.requests.length;
  assert.throws(() => resources.write("", { text: "cad" }));
  assert.equal(h.requests.length, count);
  h.reply({ outcome: "saved" });
  await assert.rejects(resources.write("file:///drawing.stl", { text: "cad" }));
  h.fail(new Error("Host declined"));
  await assert.rejects(
    resources.write("file:///drawing.stl", { text: "cad" }),
    /Host declined/,
  );
});

test("resource subscriptions deliver updates only to current listeners", async (t) => {
  const h = await host(t);
  const resources = h.extensions.resources!;
  assert.deepEqual(
    await resources.subscribe({ uri: "file:///drawing.stl" }),
    {},
  );
  assert.equal(h.requests.at(-1)?.method, "resources/subscribe");
  assert.deepEqual(h.requests.at(-1)?.params, { uri: "file:///drawing.stl" });
  const first: unknown[] = [],
    second: unknown[] = [];
  const remove = resources.addUpdateHandler((value) => {
    first.push(value);
  });
  let delivered!: () => void;
  resources.addUpdateHandler((value) => {
    second.push(value);
    delivered();
  });
  const params = { uri: "file:///drawing.stl" };
  for (let index = 0; index < 2; index++) {
    const completion = new Promise<void>((resolve) => {
      delivered = resolve;
    });
    await h.notify("notifications/resources/updated", params);
    await completion;
    remove();
  }
  assert.deepEqual(first, [
    { method: "notifications/resources/updated", params },
  ]);
  assert.equal(second.length, 2);
  assert.deepEqual(await resources.unsubscribe(params), {});
  assert.equal(h.requests.at(-1)?.method, "resources/unsubscribe");
  assert.deepEqual(h.requests.at(-1)?.params, params);
});

test("messages, model context, and file opening serialize their extension payloads", async (t) => {
  const h = await host(t);
  const params = {
    role: "user" as const,
    content: [{ type: "text" as const, text: "Explain this drawing" }],
    _meta: {
      trace: "message-1",
      "openai/message": { target: "new" as const, send: false },
    },
  };
  h.reply({ isError: false });
  assert.deepEqual(await h.extensions.message!.send(params), {
    isError: false,
  });
  assert.equal(h.requests.at(-1)?.method, "ui/message");
  assert.deepEqual(h.requests.at(-1)?.params, params);
  h.reply({ _meta: { "openai/modelContext": { updateId: "context-1" } } });
  const context = { structuredContent: { part: "bolt" } };
  assert.deepEqual(await h.extensions.modelContext!.update(context), {
    updateId: "context-1",
  });
  assert.equal(h.requests.at(-1)?.method, "ui/update-model-context");
  assert.deepEqual(h.requests.at(-1)?.params, context);
  h.reply({});
  assert.equal(await h.extensions.modelContext!.update(context), undefined);
  assert.deepEqual(
    await h.extensions.files!.open("/workspace/drawing.stl"),
    {},
  );
  assert.equal(h.requests.at(-1)?.method, "openai/files/open");
  assert.deepEqual(h.requests.at(-1)?.params, {
    path: "/workspace/drawing.stl",
  });
  assert.throws(() => h.extensions.files!.open(""));
  h.fail(new Error("Host declined"));
  await assert.rejects(h.extensions.message!.send(params), /Host declined/);
});

test("host context notifications preserve clearing and normalize older deep links", async (t) => {
  const h = await host(t);
  assert.equal(h.extensions.deepLink.getCurrent(), undefined);
  await h.context({
    "openai/deepLink": { url: "/parts/bolt?view=mesh" },
    "openai/modelContext": {
      updateId: "context-1",
      structuredContent: { part: "bolt" },
    },
  });
  assert.deepEqual(h.extensions.deepLink.getCurrent(), {
    url: "/parts/bolt?view=mesh",
  });
  assert.equal(h.extensions.modelContext!.getCurrent()?.updateId, "context-1");
  await h.context({
    "openai/deepLink": {
      path: ["parts", "hex bolt"],
      query: [["view", "mesh"]],
    },
    "openai/modelContext": null,
  });
  assert.deepEqual(h.extensions.deepLink.getCurrent(), {
    url: "/parts/hex%20bolt?view=mesh",
  });
  assert.equal(h.extensions.modelContext!.getCurrent(), null);
  await h.context({
    "openai/deepLink": 1,
    "openai/modelContext": { updateId: "" },
  });
  assert.equal(h.extensions.deepLink.getCurrent(), undefined);
  assert.equal(h.extensions.modelContext!.getCurrent(), undefined);
});

test("cursor preference applies during initialization and after context notifications", async (t) => {
  const original = Object.getOwnPropertyDescriptor(globalThis, "document");
  const styles: unknown[] = [];
  Object.defineProperty(globalThis, "document", {
    configurable: true,
    value: {
      documentElement: {
        style: { setProperty: (...args: unknown[]) => styles.push(args) },
      },
    },
  });
  t.after(() => {
    if (original) Object.defineProperty(globalThis, "document", original);
    else Reflect.deleteProperty(globalThis, "document");
  });
  const h = await host(t, features, { "openai/interactionCursor": "default" });
  assert.deepEqual(styles[0], ["--cursor-interaction", "pointer"]);
  assert.deepEqual(styles.at(-1), ["--cursor-interaction", "default"]);
  await h.context({ "openai/interactionCursor": "future-value" });
  assert.deepEqual(styles.at(-1), ["--cursor-interaction", "pointer"]);
});

import assert from "node:assert/strict";
import test from "node:test";
import {
  Client,
  InMemoryTransport,
  StreamableHTTPClientTransport,
  type ElicitResult,
} from "@modelcontextprotocol/client";
import { McpServer, createMcpHandler } from "@modelcontextprotocol/server";
import { z } from "zod";
import {
  OpenAIExtensions,
  OpenAISettingsReadResultSchema,
  requestFormInput,
} from "../src/server/index.js";

test("settings and mention search work through the MCP client/server boundary", async (t) => {
  const server = new McpServer({ name: "sdk-contract", version: "1" });
  const client = new Client({ name: "sdk-consumer", version: "1" });
  t.after(async () => {
    await client.close();
    await server.close();
  });
  const extensions = new OpenAIExtensions(server);
  let values: { units: "mm" | "in"; grid: boolean } = {
    units: "mm",
    grid: true,
  };
  const updates: unknown[] = [];
  extensions.settings.register({
    fields: {
      units: { schema: z.enum(["mm", "in"]), title: "Units" },
      grid: { schema: z.boolean(), title: "Grid" },
    },
    read: () => values,
    update: (set) => {
      updates.push(set);
      values = { ...values, ...set };
      return values;
    },
  });
  extensions.mentions.setHandler(({ query }) => ({
    items: [{ type: "resource_link", uri: `cad://${query}`, name: query }],
  }));
  assert.deepEqual(updates, []);
  const [clientTransport, serverTransport] =
    InMemoryTransport.createLinkedPair();
  await Promise.all([
    server.connect(serverTransport),
    client.connect(clientTransport),
  ]);
  assert.deepEqual(
    client.getServerCapabilities()?.experimental?.["openai/settings"],
    { readTool: "settings.read", updateTool: "settings.update" },
  );
  const tools = (await client.listTools()).tools;
  assert.equal(
    tools.find((tool) => tool.name === "settings.read")?.annotations
      ?.readOnlyHint,
    true,
  );
  assert.deepEqual(
    tools.find((tool) => tool.name === "search_mentions")?._meta?.ui,
    { visibility: ["app"] },
  );
  const read = await client.callTool({ name: "settings.read", arguments: {} });
  assert.deepEqual(
    OpenAISettingsReadResultSchema.parse(read.structuredContent).values,
    { units: "mm", grid: true },
  );
  const update = await client.callTool({
    name: "settings.update",
    arguments: { set: { grid: false } },
  });
  assert.deepEqual(updates, [{ grid: false }]);
  assert.deepEqual(update.structuredContent, {
    values: { units: "mm", grid: false },
  });
  for (const set of [{}, { grid: "false" }, { unknown: true }]) {
    assert.equal(
      (await client.callTool({ name: "settings.update", arguments: { set } }))
        .isError,
      true,
    );
  }
  assert.deepEqual(updates, [{ grid: false }]);
  const mentions = await client.callTool({
    name: "search_mentions",
    arguments: { query: "bolt" },
  });
  assert.deepEqual(mentions.structuredContent, {
    items: [{ type: "resource_link", uri: "cad://bolt", name: "bolt" }],
  });
  extensions.mentions.setHandler(() => ({ items: [] }));
  assert.deepEqual(
    (
      await client.callTool({
        name: "search_mentions",
        arguments: { query: "bolt" },
      })
    ).structuredContent,
    { items: [] },
  );
  assert.throws(
    () =>
      extensions.settings.register({
        fields: {},
        read: () => ({}),
        update: () => ({}),
      }),
    /already registered/,
  );
  Object.assign(values, { units: "invalid" });
  assert.equal(
    (await client.callTool({ name: "settings.read", arguments: {} })).isError,
    true,
  );
});

test("invalid settings definitions fail before a server is connected", () => {
  for (const schema of [
    z.object({ nested: z.string() }),
    z.string().default("mm"),
  ]) {
    const server = new McpServer({ name: "sdk-contract", version: "1" });
    assert.throws(() =>
      new OpenAIExtensions(server).settings.register({
        fields: { value: { schema, title: "Value" } },
        read: () => ({ value: "mm" }),
        update: () => ({ value: "mm" }),
      }),
    );
  }
});

const form = {
  type: "object" as const,
  properties: {
    source: {
      type: "string" as const,
      format: "uri" as const,
      "x-openai-input": {
        type: "resource" as const,
        options: [{ uri: "file:///drawing.stl", name: "Drawing" }],
      },
    },
  },
  required: ["source"],
};
const params = {
  mode: "form" as const,
  message: "Choose a drawing",
  requestedSchema: form,
};

test("legacy forms exchange extended schemas and validate answers through MCP", async (t) => {
  for (const supported of [false, true]) {
    const server = new McpServer({ name: "forms", version: "1" });
    const extensions = new OpenAIExtensions(server);
    const client = new Client(
      { name: "form-consumer", version: "1" },
      {
        capabilities: supported
          ? { extensions: { "openai/elicitation": { form: {} } } }
          : {},
      },
    );
    t.after(async () => {
      await client.close();
      await server.close();
    });
    let reply: Record<string, unknown> = {
      action: "accept",
      content: { source: "file:///drawing.stl" },
    };
    const received: unknown[] = [];
    client.setRequestHandler(
      "openai/elicitation/create",
      { params: z.unknown() },
      async (requestParams) => {
        received.push(requestParams);
        return reply;
      },
    );
    server.registerTool(
      "choose-drawing",
      { inputSchema: z.object({}) },
      async (_args, context) => ({
        content: [],
        structuredContent: await extensions.elicitInputLegacy(context, params),
      }),
    );
    const pair = InMemoryTransport.createLinkedPair();
    for (const transport of pair) {
      const send = transport.send.bind(transport);
      transport.send = (message, options) =>
        send(JSON.parse(JSON.stringify(message)), options);
    }
    await Promise.all([server.connect(pair[1]), client.connect(pair[0])]);
    const choose = () =>
      client.callTool({ name: "choose-drawing", arguments: {} });
    if (!supported) {
      assert.equal((await choose()).isError, true);
      assert.deepEqual(received, []);
      continue;
    }
    assert.deepEqual((await choose()).structuredContent, reply);
    assert.deepEqual(received, [params]);
    const invalidContents: NonNullable<ElicitResult["content"]>[] = [
      { source: "file:///other.stl" },
      {},
    ];
    for (const content of invalidContents) {
      reply = { action: "accept", content };
      assert.equal((await choose()).isError, true);
    }
    reply = { action: "unexpected" };
    assert.equal((await choose()).isError, true);
    for (const action of ["cancel", "decline"]) {
      reply = { action };
      assert.deepEqual((await choose()).structuredContent, { action });
    }
  }
});

test("MRTR exchanges preserve extended schemas and consume validated retry answers", async (t) => {
  const exchanges: {
    request: Record<string, unknown>;
    response: Record<string, unknown>;
  }[] = [];
  const saved: unknown[] = [];
  const handler = createMcpHandler(
    () => {
      const server = new McpServer({ name: "forms", version: "1" });
      server.registerTool(
        "choose-drawing",
        { inputSchema: z.object({}) },
        (_args, context) => {
          const result = requestFormInput(context, {
            ...params,
            key: "drawing",
            requestState: "resume-1",
          });
          if ("resultType" in result) return result;
          if (result.action === "accept") {
            saved.push(result.content);
            assert.equal(context.mcpReq.requestState(), "resume-1");
          }
          return { content: [], structuredContent: result };
        },
      );
      return server;
    },
    { responseMode: "json" },
  );
  t.after(() => handler.close());
  let reply: ElicitResult = {
    action: "accept",
    content: { source: "file:///drawing.stl" },
  };
  const client = new Client(
    { name: "form-consumer", version: "1" },
    {
      versionNegotiation: { mode: { pin: "2026-07-28" } },
      capabilities: {
        elicitation: { form: {} },
        extensions: { "openai/elicitation": { form: {} } },
      },
    },
  );
  t.after(() => client.close());
  client.setRequestHandler("elicitation/create", async (request) => {
    assert.deepEqual(request.params._meta?.["openai/elicitation"], {
      requestedSchema: form,
    });
    return reply;
  });
  const fetchPeer: typeof fetch = async (input, init) => {
    const request = new Request(input, init);
    const response = await handler.fetch(request.clone());
    if (request.method === "POST")
      exchanges.push({
        request: await request.json(),
        response: await response.clone().json(),
      });
    return response;
  };
  const transport = new StreamableHTTPClientTransport(
    new URL("http://sdk.test/mcp"),
    { fetch: fetchPeer },
  );
  await client.connect(transport);
  const choose = () =>
    client.callTool({ name: "choose-drawing", arguments: {} });
  assert.deepEqual((await choose()).structuredContent, reply);
  assert.deepEqual(saved, [{ source: "file:///drawing.stl" }]);
  const rounds = exchanges.filter(
    (exchange) => exchange.request.method === "tools/call",
  );
  assert.equal(rounds.length, 2);
  const first = z
    .object({
      result: z.object({
        resultType: z.literal("input_required"),
        inputRequests: z.record(z.string(), z.unknown()),
      }),
    })
    .parse(rounds[0]!.response).result;
  assert.deepEqual(first.inputRequests, {
    drawing: {
      method: "elicitation/create",
      params: {
        mode: "form",
        message: params.message,
        requestedSchema: { type: "object", properties: {} },
        _meta: { "openai/elicitation": { requestedSchema: form } },
      },
    },
  });
  const invalidContents: NonNullable<ElicitResult["content"]>[] = [
    { source: "file:///other.stl" },
    {},
  ];
  for (const content of invalidContents) {
    reply = { action: "accept", content };
    assert.equal((await choose()).isError, true);
  }
  assert.equal(saved.length, 1);
  for (const action of ["cancel", "decline"] as const) {
    reply = { action };
    assert.deepEqual((await choose()).structuredContent, { action });
  }
  const unsupported = new Client(
    { name: "unsupported", version: "1" },
    {
      versionNegotiation: { mode: { pin: "2026-07-28" } },
      capabilities: { elicitation: { form: {} } },
    },
  );
  t.after(() => unsupported.close());
  await unsupported.connect(
    new StreamableHTTPClientTransport(new URL("http://sdk.test/mcp"), {
      fetch: fetchPeer,
    }),
  );
  assert.equal(
    (await unsupported.callTool({ name: "choose-drawing", arguments: {} }))
      .isError,
    true,
  );
});

